SELECT ${pk_column}, COUNT(*) AS cnt
FROM ${table}
GROUP BY ${pk_column}
HAVING COUNT(*) > 1
ORDER BY cnt DESC
LIMIT 100;

SELECT DATE(${time_col}) AS day, COUNT(*) AS cnt
FROM ${table}
WHERE ${time_col} >= DATE_SUB(CURRENT_DATE, INTERVAL 30 DAY)
GROUP BY DATE(${time_col})
ORDER BY day;

